 useEffect(()=>{if(seenReady){try{localStorage.setItem("pna-arena-feedback-seen-v1",JSON.stringify(seen.slice(-2400)));}catch{}}},[seen,seenReady]);
 const [score,setScore]=useState(0);
 const [finished,setFinished]=useState(false);
