  setSeen(v=>[...v,message]);setFeedback(message+"|"+why);setRevealed(true);setScrollRequest(n=>n+1);if(ok){setCaseScore(v=>v+1);setScore(v=>v+1);setXp(v=>v+(difficulty==="Expert"?30:difficulty==="Clinician"?20:10));}
